        [Fact(DisplayName = "the truck > a generated world has one out past the camp")]
        public void T002_a_generated_world_has_one_out_past_the_camp()
        {
            var state = Worldgen.createWorld(2, 128);
            expect((state.vehicles ?? []).filter((v) => v.kind == "truck")).toHaveLength(1);
        }

        [Fact(DisplayName = "the truck > an expedition takes the seen truck and its fuel: there and back in half the time")]
        public void T003_an_expedition_takes_the_seen_truck_and_its_fuel_there_and_ba()
        {
            var walk = ScenarioMod.loadScenario(new Scenario { seed = 8, map = ["s" + ".".repeat(49)] });
            walk.pointsOfInterest.push(new() { id = "poi1", x = Js.I(49), y = Js.I(0), label = "ruin" });
            Commands.applyCommand(walk, new Command { type = "sendExpedition", survivorIds = [Js.NN(Js.Get(walk.survivors, 0)).id], poiId = "poi1" });
            var drive = withPoi();
            expect(Outposts.truck(drive)).toBeDefined();
            Commands.applyCommand(drive, new Command { type = "sendExpedition", survivorIds = [Js.NN(Js.Get(drive.survivors, 0)).id], poiId = "poi1" });
            expect(Js.NN(Js.Get(drive.expeditions, 0)).truck).toBe(true);
            expect(drive.items.filter((i) => i.kind == "fuel")).toHaveLength(2 - Outposts.TRUCK_FUEL);
            expect(Js.NN(Js.Get(walk.expeditions, 0)).returnTick - Js.NN(Js.Get(drive.expeditions, 0)).returnTick).toBe(((double)(49) * (Survivors.TICKS_PER_TILE)));
        }
