    /// <summary>outposts</summary>
    public class D004_outposts
    {

        [Fact(DisplayName = "outposts > an outpost stays, sends finds home each dawn, and comes back when recalled")]
        public void T005_an_outpost_stays_sends_finds_home_each_dawn_and_comes_back_w()
        {
            var state = withPoi();
            Commands.applyCommand(state, new Command { type = "sendExpedition", survivorIds = [Js.NN(Js.Get(state.survivors, 0)).id], poiId = "poi1", outpost = true });
            var x = Js.NN(Js.Get(state.expeditions, 0));
            expect(x.returnTick).toBe(Outposts.NEVER);
            var before = state.items.length;
            state.tick = Js.I(Time.DAY_LENGTH);
            Tick.tick(state);
            expect(state.items.length).toBeGreaterThan(before);
            expect(Commands.applyCommand(state, new Command { type = "recallOutpost", expeditionId = x.id }).ok).toBe(true);
            while ((state.expeditions.length > 0) && (state.tick < ((double)(3) * (Time.DAY_LENGTH))))
            {
                Tick.tick(state);
            }
            expect(Expeditions.everyone(state)).toHaveLength(state.survivors.length);
        }
    }
